/* Profit report refinement: period summaries and labour/parts split. */
(function(){
  const previousReportPage=reportPage;
  function profitDateKey(date,period){
    const d=new Date(String(date||'')+'T00:00:00'); if(Number.isNaN(d.getTime())) return '';
    if(period==='year') return String(d.getFullYear());
    if(period==='week'){
      // Group by the Monday date so week buckets are stable across year boundaries.
      const monday=new Date(d);monday.setDate(d.getDate()-((d.getDay()+6)%7));
      return 'Week of '+monday.getFullYear()+'-'+String(monday.getMonth()+1).padStart(2,'0')+'-'+String(monday.getDate()).padStart(2,'0');
    }
    return d.toISOString().slice(0,7);
  }
  function profitReport(){
    if(page!=='report-profit')return previousReportPage();
    const period=window.profitPeriod||'month', bills=[...(db.jobs||[]),...(db.sales||[])].filter(b=>b.status!=='Cancelled');
    const inRange=b=>(!reportFrom||b.date>=reportFrom)&&(!reportTo||b.date<=reportTo);
    const rows=bills.filter(inRange).map(b=>{
      const serviceIncome=(b.serviceLines||[]).reduce((sum,line)=>sum+Math.max(0,Number(line.charge||0)-Number(line.discount||0)),0);
      const partsIncome=(b.partLines||[]).reduce((sum,line)=>sum+Math.max(0,Number(line.price||0)*Number(line.qty||0)-Number(line.discount||0)),0);
      const partsProfit=(b.partLines||[]).reduce((sum,line)=>{const qty=Number(line.qty||0),sale=Number(line.price||0)*qty,cost=Number(find('parts',line.part)?.purchase||0)*qty;return sum+Math.max(0,sale-Number(line.discount||0)-cost)},0);
      return {date:b.date,bill:b.id,labour:serviceIncome,parts:partsProfit,serviceIncome,partsIncome};
    });
    const totalLabour=rows.reduce((n,r)=>n+r.labour,0),totalParts=rows.reduce((n,r)=>n+r.parts,0),labourRevenue=rows.reduce((n,r)=>n+r.serviceIncome,0),partsRevenue=rows.reduce((n,r)=>n+r.partsIncome,0),total=totalLabour+totalParts;
    const operatingExpenses=(db.expenses||[]).filter(inRange).reduce((sum,expense)=>sum+Number(expense.amount||0),0),operatingProfit=total-operatingExpenses;
    const purchaseExpenditure=(db.purchases||[]).filter(purchase=>purchase.status!=='Cancelled'&&inRange(purchase)).reduce((sum,purchase)=>sum+Number(billTotals(purchase).total||0),0),totalExpenditure=purchaseExpenditure+operatingExpenses;
    const jobCardRows=bills.filter(inRange).map(b=>{const serviceIncome=(b.serviceLines||[]).reduce((sum,line)=>sum+Math.max(0,Number(line.charge||0)-Number(line.discount||0)),0),partLines=b.partLines||[],partsIncome=partLines.reduce((sum,line)=>sum+Math.max(0,Number(line.price||0)*Number(line.qty||0)-Number(line.discount||0)),0),partsCost=partLines.reduce((sum,line)=>sum+Number(find('parts',line.part)?.purchase||0)*Number(line.qty||0),0),partsProfit=Math.max(0,partsIncome-partsCost),jobProfit=serviceIncome+partsProfit,jobIncome=serviceIncome+partsIncome,customer=b.customer?name('customers',b.customer):b.walkin||'Walk-in Customer',vehicle=b.bike?number(b.bike):b.vehicleNumber||'—';return [esc(b.id),esc(b.date||'—'),esc(customer),esc(vehicle),money(serviceIncome),money(partsIncome),money(partsCost),money(jobProfit),jobIncome?(jobProfit/jobIncome*100).toFixed(1)+'%':'0%']});
    const grouped={};for(const r of rows){const k=profitDateKey(r.date,period)||'Undated';grouped[k]??={labour:0,parts:0,expenses:0};grouped[k].labour+=r.labour;grouped[k].parts+=r.parts}
    for(const expense of db.expenses||[]){if(!inRange(expense))continue;const k=profitDateKey(expense.date,period)||'Undated';grouped[k]??={labour:0,parts:0,expenses:0};grouped[k].expenses+=Number(expense.amount||0)}
    const groupRows=Object.entries(grouped).sort((a,b)=>a[0].localeCompare(b[0])).map(([k,v])=>[esc(k),money(v.labour),money(v.parts),money(v.labour+v.parts),money(v.labour+v.parts-v.expenses),total?((v.labour+v.parts)/total*100).toFixed(1)+'%':'0%']);
    const buckets={};
    const bucketFor=date=>{const key=profitDateKey(date,period);if(!key)return null;return buckets[key]??={labour:0,parts:0,serviceIncome:0,partsIncome:0,purchases:0,expenses:0}};
    for(const r of rows){const bucket=bucketFor(r.date);if(bucket){bucket.labour+=r.labour;bucket.parts+=r.parts;bucket.serviceIncome+=r.serviceIncome;bucket.partsIncome+=r.partsIncome}}
    for(const purchase of db.purchases||[]){if(purchase.status==='Cancelled'||!inRange(purchase))continue;const bucket=bucketFor(purchase.date);if(bucket)bucket.purchases+=Number(billTotals(purchase).total||0)}
    for(const expense of db.expenses||[]){if(!inRange(expense))continue;const bucket=bucketFor(expense.date);if(bucket)bucket.expenses+=Number(expense.amount||0)}
    const chartRows=Object.entries(buckets).sort((a,b)=>a[0].localeCompare(b[0]));const ceiling=Math.max(1,...chartRows.flatMap(([,v])=>[v.labour+v.parts,v.purchases+v.expenses]));
    const periodLabel=period==='week'?'Weekly':period==='year'?'Yearly':'Monthly';
    const incomeCeiling=Math.max(1,...chartRows.flatMap(([,v])=>[v.serviceIncome,v.partsIncome]));
    const incomeChart=`<section class="panel profitChart incomeChart"><div class="panelhead"><h2>${periodLabel} Income by Source</h2></div><div class="panelbody"><div class="profitChartLegend"><span>■ Labour / Service Income</span><span>■ Spare Parts Income</span></div>${chartRows.length?chartRows.map(([bucketKey,v])=>`<div class="profitChartRow"><strong>${esc(bucketKey)}</strong><div class="profitChartBars"><div class="profitChartBar incomeLabourBar" style="width:${Math.max(1,v.serviceIncome/incomeCeiling*100)}%" title="Labour / Service Income ${money(v.serviceIncome)}"></div><div class="profitChartBar incomePartsBar" style="width:${Math.max(1,v.partsIncome/incomeCeiling*100)}%" title="Spare Parts Income ${money(v.partsIncome)}"></div></div><span>${money(v.serviceIncome)} / ${money(v.partsIncome)}</span></div>`).join(''):'<p>No dated records in this period.</p>'}<small>Income is billed labour/service and spare-parts value after line discounts, excluding GST. Values follow the selected ${periodLabel.toLowerCase()} view.</small></div></section>`;
    const incomeRows=chartRows.map(([bucketKey,v])=>[esc(bucketKey),money(v.serviceIncome),money(v.partsIncome),money(v.serviceIncome+v.partsIncome)]);
    const chart=`<section class="panel profitChart"><div class="panelhead"><h2>${periodLabel} Profit and Expenditure</h2></div><div class="panelbody"><div class="profitChartLegend"><span>■ Profit</span><span>■ Expenditure</span></div>${chartRows.length?chartRows.map(([bucketKey,v])=>`<div class="profitChartRow"><strong>${esc(bucketKey)}</strong><div class="profitChartBars"><div class="profitChartBar profitBar" style="width:${Math.max(1,(v.labour+v.parts)/ceiling*100)}%" title="Profit ${money(v.labour+v.parts)}"></div><div class="profitChartBar expenseBar" style="width:${Math.max(1,(v.purchases+v.expenses)/ceiling*100)}%" title="Expenditure ${money(v.purchases+v.expenses)}"></div></div><span>${money(v.labour+v.parts)} / ${money(v.purchases+v.expenses)}</span></div>`).join(''):'<p>No dated records in this period.</p>'}<small>Expenditure is supplier purchase invoice totals including GST, plus all recorded expenses including salary payments. Purchases use purchase dates; expenses use expense dates; profit uses sale/job dates. Chart and breakdown follow the selected ${periodLabel.toLowerCase()} view.</small></div></section>`;
    const expenditureRows=chartRows.map(([bucketKey,v])=>[esc(bucketKey),money(v.purchases),money(v.expenses),money(v.purchases+v.expenses)]);
    const expenditureCeiling=Math.max(1,...chartRows.flatMap(([,v])=>[v.purchases,v.expenses]));
    const expenditureChart=`<section class="panel profitChart expenditureChart"><div class="panelhead"><h2>${periodLabel} Expenditure by Source</h2></div><div class="panelbody"><div class="profitChartLegend"><span>■ Spare Parts Purchases</span><span>■ Other Expenses</span></div>${chartRows.length?chartRows.map(([bucketKey,v])=>`<div class="profitChartRow"><strong>${esc(bucketKey)}</strong><div class="profitChartBars"><div class="profitChartBar purchaseExpenseBar" style="width:${Math.max(1,v.purchases/expenditureCeiling*100)}%" title="Spare Parts Purchases ${money(v.purchases)}"></div><div class="profitChartBar otherExpenseBar" style="width:${Math.max(1,v.expenses/expenditureCeiling*100)}%" title="Other Expenses ${money(v.expenses)}"></div></div><span>${money(v.purchases)} / ${money(v.expenses)}</span></div>`).join(''):'<p>No dated records in this period.</p>'}<small>Other Expenses include recorded salary payments and other expense entries. Values follow the selected ${periodLabel.toLowerCase()} view.</small></div></section>`;
    const exportSection=(title,headers,rows)=>{const csv=[[title],headers,...rows.map(row=>row.map(cell=>String(cell).replace(/<[^>]*>/g,'')))].map(row=>row.map(cell=>'"'+String(cell).replace(/"/g,'""')+'"').join(',')).join('\r\n');download('\ufeff'+csv,'BIKE-DOCTOR-'+title.replace(/[^a-z0-9]+/gi,'-')+'-'+today()+'.csv','text/csv;charset=utf-8')};
    return `<div class="intro"><h2>Profit Report</h2><p>Profit split by labour/service and spare parts, excluding GST from earnings.</p></div>`+
      `<div class="profitCompact">${summary([['TOTAL PROFIT',money(total)],['OPERATING PROFIT',money(operatingProfit)],['TOTAL EXPENDITURE',money(totalExpenditure)],['LABOUR / SERVICE PROFIT',money(totalLabour)],['LABOUR / SERVICE PROFIT MARGIN',labourRevenue?(totalLabour/labourRevenue*100).toFixed(1)+'%':'0%'],['SPARE PARTS PROFIT',money(totalParts)],['SPARE PARTS PROFIT MARGIN',partsRevenue?(totalParts/partsRevenue*100).toFixed(1)+'%':'0%']])}</div><p class="profitOperatingNote">Total Expenditure = supplier purchase invoice totals including GST + all recorded expenses. Operating Profit remains Total Profit minus recorded expenses; purchase costs are already represented in Spare Parts Profit and are not deducted a second time.</p>`+`<div class="toolbar"><label>View <select id="profitPeriod"><option value="week" ${period==='week'?'selected':''}>Weekly</option><option value="month" ${period==='month'?'selected':''}>Monthly</option><option value="year" ${period==='year'?'selected':''}>Yearly</option></select></label><input id="search" class="search" placeholder="Search this report…" aria-label="Search report" value="${esc(search)}"><label>From <input type="date" id="reportFrom" value="${esc(reportFrom)}"></label><label>To <input type="date" id="reportTo" value="${esc(reportTo)}"></label><span class="spacer"></span>${btn('Print / Preview','printReport','secondary','print')}${btn('Export Excel','export','success','download')}</div>`+`<section class="panel profitAnalysis"><div class="panelhead"><h2>Profit and Financial Analysis</h2></div><div class="panelbody"><div class="profitReportGroup incomeGroup">${incomeChart}<h3>${periodLabel} Income by Source</h3>${table(['Period','Labour / Service Income','Spare Parts Income','Total Income'],incomeRows)}</div>`+`<div class="profitReportGroup profitGroup">${chart}${table(['Period','Labour / Service Profit','Spare Parts Profit','Total Profit','Operating Profit','Share of Total'],groupRows)}</div>`+`<div class="profitReportGroup expenditureGroup">${expenditureChart}<h3>${periodLabel} Expenditure</h3>${table(['Period','Spare Parts Purchases','Other Expenses','Total Expenditure'],expenditureRows)}</div><section class="panel jobMarginReport"><div class="panelhead"><h2>Job Card-wise Profit Margin</h2></div><div class="panelbody"><p class="profitOperatingNote">Job-card margin uses billed income after line discounts. Spare-part cost uses the saved purchase reference; GST is excluded.</p>${table(['Job Card','Date','Customer','Vehicle','Labour / Service Income','Spare Parts Income','Spare Parts Cost','Total Profit','Margin'],jobCardRows)}<p class="profitCalculationHint"><strong>Calculation hint:</strong> Labour / Service Income = service charges − line discounts. Spare Parts Income = selling amount − line discounts. Spare Parts Cost = quantity × saved purchase reference. Total Profit = Labour / Service Income + Spare Parts Income − Spare Parts Cost. Profit Margin = Total Profit ÷ Total Income × 100. GST is excluded.</p></div></section></div></section>`;
  }
  reportPage=profitReport;
  const oldBind=bindPage;
  bindPage=function(){oldBind();if($('#profitPeriod'))$('#profitPeriod').onchange=e=>{window.profitPeriod=e.target.value;render()};if(page==='report-profit'){const root=$('.profitAnalysis');if(root&&!root.dataset.sectionExports){root.dataset.sectionExports='true';const exportTable=(group,title)=>{const table=group?.querySelector('table');if(!table)return;const rows=[...table.querySelectorAll('tr')].map(tr=>[...tr.children].map(cell=>cell.innerText.trim()));const csv=rows.map(row=>row.map(cell=>'"'+cell.replace(/"/g,'""')+'"').join(',')).join('\r\n');download('\ufeff'+csv,'BIKE-DOCTOR-'+title.replace(/[^a-z0-9]+/gi,'-')+'-'+today()+'.csv','text/csv;charset=utf-8')};const groups=[['incomeGroup','Monthly Income by Source'],['expenditureGroup','Total Expenditure by Source'],['profitGroup','Profit vs Expenditure'],['jobMarginReport','Job Card-wise Profit Margin']];groups.forEach(([cls,title])=>{const group=root.querySelector('.'+cls);if(!group)return;const heading=group.querySelector('h3')||group.querySelector('.panelhead h2')||group.insertBefore(document.createElement('h3'),group.firstChild);if(!heading.textContent.trim())heading.textContent=title;const button=document.createElement('button');button.type='button';button.className='btn success small profitExport';button.textContent='Export Excel';button.dataset.profitExport=cls;button.onclick=()=>exportTable(group,title);heading.append(' ',button)})}}}
  if(page==='report-profit')render();
})();
/* Keep visible calculation hints aligned with the current income, expenditure and margin rules. */
(function(){
  const updateHints=()=>{
    document.querySelectorAll('#content .intro p').forEach(el=>{if(el.textContent.includes('based on current sample purchase costs'))el.textContent='Parts margin before tax and discounts; cost uses the saved purchase reference for each part line.'});
    document.querySelectorAll('.profitAnalysis small,.profitCalculationHint').forEach(el=>{
    if(el.textContent.includes('Income is billed labour/service'))el.textContent='Income includes job-card labour/service lines and counter spare-part sales after line discounts. GST is excluded from income. Values follow the selected period.';
    if(el.textContent.includes('Other Expenses include recorded salary payments'))el.textContent='Other Expenses include every saved expense entry, including salary advances/payments and other operating expenses. Spare Parts Purchases use saved supplier invoice totals including GST. Values follow the selected period.';
    if(el.textContent.includes('Spare-part cost uses the saved purchase reference'))el.innerHTML='<strong>Calculation hint:</strong> Labour / Service Income = service charges − line discounts. Spare Parts Income = selling amount − line discounts. Spare Parts Cost = quantity × saved purchase reference. Total Profit = Labour / Service Income + Spare Parts Income − Spare Parts Cost. Profit Margin = Total Profit ÷ Total Income × 100. GST is excluded; purchase expenditure is reported separately and is not deducted twice.';
    });
  };
  new MutationObserver(updateHints).observe(document.body,{childList:true,subtree:true}); updateHints();
})();
